object Solution { def maxProfit(k: Int, p: Array[Int]): Int = { val n = p.length; if (n == 0 || k == 0) return 0; if (k >= n / 2) { var ans = 0; for (i <- 1 until n) ans += math.max(p(i) - p(i - 1), 0); return ans }; val buy = Array.fill(k + 1)(Int.MaxValue); val sell = Array.fill(k + 1)(0); for (price <- p; t <- 1 to k) { buy(t) = math.min(buy(t), price - sell(t - 1)); sell(t) = math.max(sell(t), price - buy(t)) }; sell(k) } }
